import{_ as n,C as a,o as l,c as d,j as e,a as c,E as o,a6 as r}from"./chunks/framework.CD0vXS2f.js";const x=JSON.parse('{"title":"01 · Executive Thesis & Regional AI Failure Modes","description":"Business continuity architecture for regulated Microsoft Foundry workloads—aligning residency boundaries, cold-cache failover surges, and stateful session/search dependencies.","frontmatter":{"title":"01 · Executive Thesis & Regional AI Failure Modes","description":"Business continuity architecture for regulated Microsoft Foundry workloads—aligning residency boundaries, cold-cache failover surges, and stateful session/search dependencies."},"headers":[],"relativePath":"playbooks/multi-region-bcp/01-executive-thesis.md","filePath":"playbooks/multi-region-bcp/01-executive-thesis.md","lastUpdated":1795642852816,"verifiedStamp":"2026-11-25 13:40 PST"}'),g={name:"playbooks/multi-region-bcp/01-executive-thesis.md"};function u(h,t,f,p,y,m){const s=a("PlaybookMeta"),i=a("PageBrief");return l(),d("div",null,[t[0]||(t[0]=e("h1",{id:"_01-·-executive-thesis-regional-ai-failure-modes",tabindex:"-1"},[c("01 · Executive Thesis & Regional AI Failure Modes "),e("a",{class:"header-anchor",href:"#_01-·-executive-thesis-regional-ai-failure-modes","aria-label":'Permalink to "01 · Executive Thesis & Regional AI Failure Modes"'},"​")],-1)),o(s,{track:"03 · Multi-Region Foundry BCP, Residency & Failover Drills",provenance:"Customer-Zero Validated (Regulated Multi-Region Enterprise AI Stamp)",governance:"Sanitized · Peer Reviewed · IP Screened",owners:"John Luo (@jluocsa) · Co-Authors Welcome",verified:"2026-11-19 22:12 PST",status:"Live v2.0",paperHref:"/papers/enterprise-foundry-platform-blueprint",paperLabel:"Full-Stack Blueprint →",studioHref:"/studio/#bcp",studioLabel:"BCP & Surge Advisor →"}),o(i,{stage:"start",readTime:"4 min read",problem:"Failing over an LLM endpoint alone leaves enterprise agents broken if regional data-processing boundaries are violated, secondary KV caches choke on cold-start surges, or Cosmos/AI Search state lags behind.",takeaway:"Design Business Continuity at the AI Stamp level: pair Data-Zone/Regional PTU-M with secondary PAYG surge capacity, synchronize Cosmos DB + AI Search stamps, and verify <15s cutover via quarterly game-day drills.",csaUse:"Use the 4-failure-mode diagram and decision table below to align Risk/Compliance, Cloud Infrastructure, and AI Platform teams."}),t[1]||(t[1]=r('<h2 id="why-traditional-stateless-web-dr-fails-for-enterprise-ai" tabindex="-1">Why Traditional Stateless Web DR Fails for Enterprise AI <a class="header-anchor" href="#why-traditional-stateless-web-dr-fails-for-enterprise-ai" aria-label="Permalink to &quot;Why Traditional Stateless Web DR Fails for Enterprise AI&quot;">​</a></h2><p>Most cloud disaster-recovery runbooks assume stateless compute tiers where Region B can immediately serve 100% of Region A&#39;s traffic at identical unit capacity. Production Microsoft Foundry platforms introduce <strong>four AI-specific continuity constraints</strong> <span class="ev-badge ev-m">[M]</span> <span class="ev-badge ev-arch">[Arch]</span>:</p><ol><li><strong>Data-Processing vs. Data-at-Rest Residency:</strong> A <code>Global</code> deployment stores configuration metadata in the resource region, whereas inference compute may execute globally <span class="ev-badge ev-m">[M]</span>. Regulated workloads bound by geographic sovereignty must select <strong>Data Zone (<code>US</code> / <code>EU</code>)</strong> or <strong>Regional</strong> SKUs on <em>both</em> primary and failover legs <span class="ev-badge ev-m">[M]</span>.</li><li><strong>Independent Regional Quota &amp; PTU Reservations:</strong> Provisioned Throughput (<code>PTU-M</code>) capacity is reserved per deployment and does <strong>not</strong> automatically float across regions during an outage <span class="ev-badge ev-m">[M]</span>. Doubling reserved PTUs idle in Region B costs <code>2.0×</code> year-round unless paired with an <strong>Active-Passive PTU-M + Secondary Standard PAYG / Warm-Anchor</strong> topology <span class="ev-badge ev-arch">[Arch]</span>.</li><li><strong>The Cold-Cache Regional Cutover Surge:</strong> Prompt KV caches are <strong>strictly local</strong> to each deployment/stamp <span class="ev-badge ev-m">[M]</span>. When an active workload running at <code>80%</code> prefix cache reuse fails over to a cold secondary region, cached hits drop to <code>0%</code> for the first <code>5–15 minutes</code>, spiking normalized input TPM by <strong><code>1.8×–2.56×</code></strong> right at the moment of cutover <span class="ev-badge ev-arch">[Arch]</span>.</li><li><strong>Coupled Stateful Agent Dependencies:</strong> Multi-turn agents depend on <strong>Azure Cosmos DB</strong> thread/checkpoint state and <strong>Azure AI Search</strong> (<code>Foundry IQ</code>) knowledge indexes. Failing over the model endpoint while leaving AI Search or session state stranded in an unreachable primary region still causes <code>100%</code> turn failure <span class="ev-badge ev-arch">[Arch]</span>.</li></ol>',3)),t[2]||(t[2]=e("div",{class:"arch-diagram"},[e("svg",{viewBox:"0 0 760 192",role:"img","aria-labelledby":"pb3-t1-title pb3-t1-desc","font-family":"Segoe UI, Inter, -apple-system, sans-serif"},[e("title",{id:"pb3-t1-title"},"Multi-Region Enterprise AI Stamp Continuity Architecture"),e("desc",{id:"pb3-t1-desc"},"Shows Primary Stamp (East US 2: APIM Gateway, Foundry PTU-M + PAYG, Cosmos DB Write Region, AI Search Stamp A) replicating state to Secondary Stamp (Central US / West US 3: APIM Gateway, Warm Min-PTU + Standard PAYG Cold-Cache Surge Buffer, Cosmos DB Automatic Failover, AI Search Stamp B)."),e("defs",null,[e("marker",{id:"bcp-arr",markerWidth:"8",markerHeight:"8",refX:"7",refY:"4",orient:"auto"},[e("path",{d:"M0 0 L8 4 L0 8Z",fill:"#0f766e"})])]),e("rect",{x:"8",y:"14",width:"328",height:"146",rx:"7",fill:"#eaf7f5",stroke:"#0f766e","stroke-width":"1.5"}),e("text",{x:"18",y:"33","font-size":"9.4","font-weight":"700",fill:"#115e59"},"Primary AI Stamp (e.g., East US 2 · Active)"),e("rect",{x:"18",y:"43",width:"308",height:"48",rx:"5",fill:"#ffffff",stroke:"#0f766e"}),e("text",{x:"26",y:"59","font-size":"8.6","font-weight":"700",fill:"#115e59"},"APIM Gateway + Foundry Primary PTU-M (170 PTUs)"),e("text",{x:"26",y:"73","font-size":"8.0",fill:"#334e68"},"Warm Pos 1–6 KV cache (80%+ hit) + local Standard spillover"),e("rect",{x:"18",y:"99",width:"308",height:"48",rx:"5",fill:"#edf3fb",stroke:"#5b87b2"}),e("text",{x:"26",y:"115","font-size":"8.6","font-weight":"700",fill:"#183e62"},"Stateful Tier: Cosmos DB + AI Search Stamp A + ADLS"),e("text",{x:"26",y:"129","font-size":"8.0",fill:"#334e68"},"Thread checkpoints, workpaper lineage & grounded index"),e("pre",null,[e("code",null,'<path d="M336 67 H420" stroke="#b45309" stroke-width="1.9" stroke-dasharray="5 3" marker-end="url(#bcp-arr)"/> <text x="378" y="57" text-anchor="middle" font-size="7.8" font-weight="700" fill="#b45309">429 / 5xx Cutover (&lt;15s)</text> <path d="M336 123 H420" stroke="#0f766e" stroke-width="1.8" marker-end="url(#bcp-arr)"/> <text x="378" y="114" text-anchor="middle" font-size="7.8" font-weight="700" fill="#0f766e">Continuous Geo-Sync</text> <rect x="424" y="14" width="328" height="146" rx="7" fill="#fff7eb" stroke="#d97706" stroke-width="1.4"/> <text x="434" y="33" font-size="9.4" font-weight="700" fill="#92400e">Secondary DR AI Stamp (Same Data Zone · Standby)</text> <rect x="434" y="43" width="308" height="48" rx="5" fill="#ffffff" stroke="#d97706"/> <text x="442" y="59" font-size="8.6" font-weight="700" fill="#92400e">Warm Min-PTU Anchor + High-TPM Standard PAYG</text> <text x="442" y="73" font-size="8.0" fill="#92400e">Absorbs 2.56× cold-cache surge while secondary KV warms</text> <rect x="434" y="99" width="308" height="48" rx="5" fill="#edf3fb" stroke="#5b87b2"/> <text x="442" y="115" font-size="8.6" font-weight="700" fill="#183e62">Stateful Tier: Cosmos Multi-Region + AI Search Stamp B</text> <text x="442" y="129" font-size="8.0" fill="#334e68">Pre-indexed from GZRS ADLS · Pinned model snapshot</text> <text x="10" y="178" font-size="8.3" fill="#526c80">Cohesive stamp continuity: inference, gateway, session checkpoints, and search indexes fail over within one residency boundary.</text> ')])])],-1)),t[3]||(t[3]=r('<hr><h2 id="core-continuity-questions-answered-in-playbook-03" tabindex="-1">Core Continuity Questions Answered in Playbook 03 <a class="header-anchor" href="#core-continuity-questions-answered-in-playbook-03" aria-label="Permalink to &quot;Core Continuity Questions Answered in Playbook 03&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Question</th><th style="text-align:left;">Verified Architectural Answer</th><th style="text-align:left;">Chapter</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>When can we use <code>Data Zone Provisioned</code> vs. strict <code>Regional Provisioned</code>?</strong></td><td style="text-align:left;">Use <strong>Data Zone (<code>US</code> / <code>EU</code>)</strong> whenever contracts permit US-wide or EU-wide processing (higher quota liquidity + lower minimum PTUs on <code>gpt-6-astra</code>/<code>6.1-sol</code>); reserve <strong>Regional</strong> for strict single-country mandates <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;"><a href="./02-residency-and-sku-matrix">02 · Residency &amp; SKU Matrix</a></td></tr><tr><td style="text-align:left;"><strong>Must we pay <code>2×</code> reserved PTUs year-round to achieve <code>&lt;15s</code> regional RTO?</strong></td><td style="text-align:left;">Only for Tier-0 workloads prohibiting any PAYG latency variance. Most regulated Tier-1 workloads achieve <code>&lt;15s</code> RTO at <code>1.00×–1.15×</code> PTU cost by pairing Primary PTU-M with Secondary Standard PAYG (plus optional <code>15–25</code> PTU warm anchor) <span class="ev-badge ev-arch">[Arch]</span>.</td><td style="text-align:left;"><a href="./03-active-active-vs-standby-math">03 · Standby &amp; Cold-Cache Math</a></td></tr><tr><td style="text-align:left;"><strong>How do we keep Azure AI Search and Cosmos DB consistent during failover?</strong></td><td style="text-align:left;">Ingest source documents once to <code>GZRS</code> ADLS Gen2, run independent AI Search indexers per stamp, and enable Cosmos DB multi-region writes or managed failover <span class="ev-badge ev-m">[M]</span> <span class="ev-badge ev-arch">[Arch]</span>.</td><td style="text-align:left;"><a href="./04-stateful-stamp-failover">04 · Stateful Stamp Failover</a></td></tr><tr><td style="text-align:left;"><strong>How do we prove DR readiness to auditors without disrupting live users?</strong></td><td style="text-align:left;">Run quarterly Game-Day fault injection + automated snapshot-parity audits against <code>B1–B12</code>.</td><td style="text-align:left;"><a href="./05-gameday-failover-drills">05 · Game-Day Drills &amp; B1–B12</a></td></tr></tbody></table>',3))])}const b=n(g,[["render",u]]);export{x as __pageData,b as default};
